const ticketPeriodStats = `-- name: TicketPeriodStats :many

SELECT (CASE WHEN $1::text = 'area' THEN t.area_id ELSE t.client_id END)::uuid AS key_id,
  count(*) FILTER (WHERE t.resolved_at >= $2::timestamptz AND t.resolved_at < $3::timestamptz)::int AS resolved,
  count(*) FILTER (WHERE t.resolved_at >= $2::timestamptz AND t.resolved_at < $3::timestamptz
    AND t.sla_resolution_due_at IS NOT NULL)::int AS with_sla,
  count(*) FILTER (WHERE t.resolved_at >= $2::timestamptz AND t.resolved_at < $3::timestamptz
    AND t.sla_resolution_due_at IS NOT NULL
    AND t.resolved_at <= t.sla_resolution_due_at + make_interval(secs => t.sla_paused_seconds))::int AS in_sla,
  count(*) FILTER (WHERE t.created_at >= $2::timestamptz AND t.created_at < $3::timestamptz)::int AS created,
  COALESCE(avg(EXTRACT(EPOCH FROM (t.first_responded_at - t.created_at))) FILTER (
    WHERE t.created_at >= $2::timestamptz AND t.created_at < $3::timestamptz
      AND t.first_responded_at IS NOT NULL AND t.first_responded_at >= t.created_at), 0)::float8 AS avg_response_secs,
  COALESCE(avg(EXTRACT(EPOCH FROM (t.resolved_at - t.created_at))) FILTER (
    WHERE t.resolved_at >= $2::timestamptz AND t.resolved_at < $3::timestamptz
      AND t.resolved_at >= t.created_at), 0)::float8 AS avg_resolution_secs
FROM tickets t
WHERE t.merged_into_id IS NULL AND NOT t.glpi_deleted
  AND (t.resolved_at >= $2::timestamptz OR t.created_at >= $2::timestamptz)
GROUP BY 1
`

type TicketPeriodStatsParams struct {
	By     string             `json:"by"`
	FromAt pgtype.Timestamptz `json:"from_at"`
	ToAt   pgtype.Timestamptz `json:"to_at"`
}

type TicketPeriodStatsRow struct {
	KeyID             uuid.UUID `json:"key_id"`
	Resolved          int32     `json:"resolved"`
	WithSla           int32     `json:"with_sla"`
	InSla             int32     `json:"in_sla"`
	Created           int32     `json:"created"`
	AvgResponseSecs   float64   `json:"avg_response_secs"`
	AvgResolutionSecs float64   `json:"avg_resolution_secs"`
}

// ===== Indicadores (§4.4.8) =====
// Por cliente o por área (by = 'area'): resueltos y en SLA del período,
// creados y tiempos medios de 1.ª respuesta y resolución.
func (q *Queries) TicketPeriodStats(ctx context.Context, arg TicketPeriodStatsParams) ([]TicketPeriodStatsRow, error) {
	rows, err := q.db.Query(ctx, ticketPeriodStats, arg.By, arg.FromAt, arg.ToAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TicketPeriodStatsRow
	for rows.Next() {
		var i TicketPeriodStatsRow
		if err := rows.Scan(
			&i.KeyID,
			&i.Resolved,
			&i.WithSla,
			&i.InSla,
			&i.Created,
			&i.AvgResponseSecs,
			&i.AvgResolutionSecs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

